window.VO = [{"id":"s01","text":"Diwali's sky is missing a colour.","at":0.9,"t0":0.45,"t1":2.46},{"id":"s02","text":"Every colour up there is a burning metal.","at":5.82,"t0":2.91,"t1":5.13},{"id":"s03","text":"Red is strontium. Orange, calcium. Yellow, sodium. Green, barium.","at":11.06,"t0":5.53,"t1":10.11},{"id":"s04","text":"But a true blue? Almost impossible to find.","at":21.22,"t0":10.61,"t1":13.495},{"id":"s05","text":"Blue comes from copper.","at":27.99,"t0":13.995,"t1":15.38},{"id":"s06","text":"And copper's blue is fragile. Too hot, and it washes out to white.","at":31.56,"t0":15.78,"t1":19.72},{"id":"s07","text":"Too cool, and it barely glows.","at":40.14,"t0":20.07,"t1":21.955},{"id":"s08","text":"But fireworks have to burn hot. So blue lives in a tiny window.","at":44.81,"t0":22.405,"t1":26.31},{"id":"s09","text":"Makers even add chlorine, sometimes from plastic, to help it glow.","at":53.52,"t0":26.76,"t1":30.81},{"id":"s10","text":"A perfect blue is the holy grail of fireworks.","at":62.52,"t0":31.26,"t1":34.065},{"id":"s11","text":"And in India, green has a problem too.","at":69.33,"t0":34.665,"t1":37.09},{"id":"s12","text":"In two thousand eighteen, India's Supreme Court banned barium from firecrackers. Barium makes green.","at":75.08,"t0":37.54,"t1":44.02},{"id":"s13","text":"So the green in green crackers means less pollution, not the colour.","at":89.14,"t0":44.57,"t1":48.47},{"id":"s14","text":"If you spot a deep blue this Diwali, you're watching the hardest colour in chemistry.","at":97.94,"t0":48.97,"t1":53.64}];
